<?php
require_once __DIR__ . '/../includes/bootstrap.php';$pageTitle='Inventory';$activePage='inventory/index.php';$basePath='../';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$product=(int)($_POST['product_id']??0);$type=(string)($_POST['movement_type']??'');$amount=positive_decimal($_POST['quantity']??null,'Quantity');$remarks=trim((string)($_POST['remarks']??''));if($remarks==='')$remarks='Manual stock adjustment';$pdo->beginTransaction();if($type==='CUSTOMER_RETURN'){$row=inventory_row($pdo,$product);apply_inbound($pdo,$product,$type,$amount,(float)$row['average_cost'],$remarks,'ADJ-'.date('YmdHis'));}elseif(in_array($type,['INTERNAL_USE','DAMAGE','SUPPLIER_RETURN'],true)){apply_outbound($pdo,$product,$type,$amount,$remarks,'ADJ-'.date('YmdHis'));}else{throw new RuntimeException('Choose a valid adjustment type.');}$pdo->commit();flash('success','Stock adjustment recorded.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','Adjustment failed: '.$e->getMessage());}redirect('index.php');}
$products=product_options($pdo);$rows=$pdo->query('SELECT p.product_id,p.product_name,p.unit,p.reorder_level,i.quantity_available,i.average_cost,i.last_updated,c.category_name FROM products p JOIN inventory i ON i.product_id=p.product_id JOIN categories c ON c.category_id=p.category_id ORDER BY p.product_name')->fetchAll();$moves=$pdo->query('SELECT sm.*,p.product_name,p.unit FROM stock_movements sm JOIN products p ON p.product_id=sm.product_id ORDER BY sm.movement_date DESC,sm.movement_id DESC LIMIT 40')->fetchAll();
require __DIR__.'/../includes/header.php';?>
<section class="page-heading"><div><p class="eyebrow">STOCK CONTROL</p><h1>Inventory</h1><p class="muted">Current stock is a summary; stock movements keep the full history.</p></div></section>
<div class="two-column"><section class="panel"><h2>Record stock adjustment</h2><p class="muted">Use this for internal usage, damage, supplier returns or customer returns.</p><form method="post" class="form-grid"><?=csrf_field()?><label class="full">Product<select name="product_id" required><option value="">Select product</option><?php foreach($products as $p):?><option value="<?=(int)$p['product_id']?>"><?=e($p['product_name'])?> (<?=e($p['unit'])?>)</option><?php endforeach;?></select></label><label class="full">Movement type<select name="movement_type" required><option value="">Select type</option><option value="INTERNAL_USE">Internal usage (stock out)</option><option value="DAMAGE">Damaged stock (stock out)</option><option value="SUPPLIER_RETURN">Supplier return (stock out)</option><option value="CUSTOMER_RETURN">Customer return (stock in)</option></select></label><label>Quantity<input type="number" name="quantity" min="0.001" step="0.001" required></label><label>Remarks<input name="remarks" maxlength="150" placeholder="Reason / details"></label><div class="form-actions full"><button class="btn primary">Save adjustment</button></div></form></section>
<section class="panel"><h2>Inventory position</h2><div class="table-wrap"><table><thead><tr><th>Product</th><th>Available</th><th>Reorder</th><th>Avg. cost</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):$low=(float)$r['quantity_available']<=(float)$r['reorder_level'];?><tr><td><strong><?=e($r['product_name'])?></strong><small class="subline"><?=e($r['category_name'])?></small></td><td><?=qty($r['quantity_available'])?> <?=e($r['unit'])?></td><td><?=qty($r['reorder_level'])?></td><td><?=money($r['average_cost'])?></td><td><span class="pill <?=$low?'pill-low':'pill-ok'?>"><?=$low?'Low stock':'In stock'?></span></td></tr><?php endforeach;?></tbody></table></div></section></div>
<section class="panel"><div class="panel-heading"><h2>Stock movement history</h2><span class="count-label">Latest 40</span></div><div class="table-wrap"><table><thead><tr><th>Date / time</th><th>Product</th><th>Type</th><th>Quantity</th><th>Unit cost</th><th>Reference</th><th>Remarks</th></tr></thead><tbody><?php foreach($moves as $m):?><tr><td><?=e(date('d M Y H:i',strtotime($m['movement_date'])))?></td><td><?=e($m['product_name'])?></td><td><span class="pill <?=in_array($m['movement_type'],IN_MOVEMENTS,true)?'pill-in':'pill-out'?>"><?=e(str_replace('_',' ',$m['movement_type']))?></span></td><td><?=qty($m['quantity'])?> <?=e($m['unit'])?></td><td><?=money($m['unit_cost'])?></td><td><?=e($m['reference_code'])?></td><td><?=e($m['remarks'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php';?>
